def gen_recv(recv_name, type_name="T", has_return=False):
    ret = " int {return 0}" if has_return else " {}"
    code=f'package foo\ntype {type_name} struct{{A int}}\nfunc ({recv_name} {type_name}) Foo(){ret}\n' if recv_name not in ["(T)", "(T*)"] else f'package foo\ntype {type_name} struct{{A int}}\nfunc {recv_name} Foo(){ret}\n'
