// Helpers for generation

func isExported(name string) bool {
	if name == "" {
		return false
	}
	c := name[0]
	return c >= 'A' && c <= 'Z'
}

func title(s string) string {
	if s == "" {
		return ""
	}
	// Use simple Title: first letter upper, rest as is (like strings.Title for single word)
	// strings.Title is deprecated but we replicate for ASCII
	if len(s) == 0 {
		return s
	}
	// Find first letter?
	// For our purposes, just upper first byte if lower
	b := s[0]
	if b >= 'a' && b <= 'z' {
		return string(b - 32) + s[1:]
	}
	return s
}

// GoTitle replicates strings.Title for our matching (first letter of each word? but we only need first?)
func goTitle(s string) string {
	// Use strings.Title logic: capitalize first letter after non-letter?
	// For simplicity, use title() for whole string? Actually strings.Title("t2Foo") -> "T2Foo" (first letter upper)
	// That's same as title(s) for our cases (since no spaces)
	// But for "fooBar", title -> "FooBar" (first upper)
