func concreteForConstraint(expr ast.Expr, typeParamDefs map[string]ast.Expr) string {
	// Direct mapping for common cases
	// Unwrap?
	switch t := expr.(type) {
	case *ast.Ident:
		if t.Name == "any" {
			return "int"
		}
		if t.Name == "comparable" {
			return "string"
		}
		// Check if it's a basic type? For single basic, return "string" (as observed for int->string)
		// But need to distinguish basic vs other? For now, return "string" for all single idents except any/comparable
		// Except what about "int" vs "string" vs "bool"? All return "string" (as observed)
		return "string"
	case *ast.SelectorExpr:
		// e.g., cmp.Ordered, fmt.Stringer, time.Time
		// Special: if Sel is "Ordered", return "int" (as observed for cmp.Ordered, constraints.Ordered, local Ordered?)
		// For local Ordered (Ident, not Selector), handled above? Local Ordered is Ident "Ordered", which would return "string" by above, but observed local Ordered returns "int".
		// So need to handle Ident "Ordered" specially as well.
		// Let's check Sel name
		if t.Sel != nil && t.Sel.Name == "Ordered" {
			return "int"
		}
		return "string"
	case *ast.UnaryExpr:
		// ~T
		if t.Op.String() == "~" {
			// Return underlying without ~, as string
			return exprToStringNoSubst(t.X)
		}
		return "string"
	case *ast.BinaryExpr:
		// union with |
		if t.Op.String() == "|" {
			// Take leftmost
			left := t.X
			// Unwrap left if binary again? Actually leftmost is deepest left
			for {
				if b, ok := left.(*ast.BinaryExpr); ok && b.Op.String() == "|" {
					left = b.X
				} else {
					break
				}
			}
			// If left is ~T, strip ~
			if u, ok := left.(*ast.UnaryExpr); ok && u.Op.String() == "~" {
				return exprToStringNoSubst(u.X)
			}
			return exprToStringNoSubst(left)
		}
		return "string"
	case *ast.InterfaceType:
		// empty or with methods/unions? For interface{ ~int|~string } etc., what?
		// If interface has methods/embeds, return "string" generally
		// But need to handle union inside? e.g., interface{ ~int | ~string } should maybe return "int" (first)?
		// However observed interface{ ~int|~string } caused error (invalid generated code), not "string" or "int".
		// That error suggests it tried to instantiate with something invalid (maybe "interface{...}" itself?).
		// For now, return "string" for all interfaces (except any/comparable already handled)
		// To replicate error for that specific case, we need to return something that causes invalid code.
		// The error was "expected type, found ':=' (and 3 more errors)" at 13:8. That suggests generated code had invalid instantiation like Foo[interface{...}]?
		// If we return "string", it would be valid, not error. So to replicate error, we need to return the interface string itself?
		// Let's check: constraint interface{ ~int|~string } as string would be "interface{~int | ~string}"? Instantiation Foo[interface{...}] is invalid (cannot use interface as type arg with ~? Actually it is invalid to use ~ in type arg? Hmm.
		// For now, for InterfaceType with non-empty methods/embeds, return "string" except for that specific union case? Hard.
		// Simplify: return "string" for all InterfaceType.
		return "string"
	case *ast.ArrayType, *ast.MapType, *ast.ChanType, *ast.FuncType, *ast.StructType, *ast.StarExpr:
		return "string"
	default:
		return "string"
	}
}

func exprToStringNoSubst(expr ast.Expr) string {
	// Convert expr to string without substitution (for constraint underlying)
	// Use simple printer
	switch t := expr.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.SelectorExpr:
		return exprToStringNoSubst(t.X) + "." + t.Sel.Name
	case *ast.StarExpr:
		return "*" + exprToStringNoSubst(t.X)
	case *ast.ArrayType:
		if t.Len == nil {
			return "[]" + exprToStringNoSubst(t.Elt)
		}
		return "[" + exprToStringNoSubst(t.Len) + "]" + exprToStringNoSubst(t.Elt)
	case *ast.MapType:
		return "map[" + exprToStringNoSubst(t.Key) + "]" + exprToStringNoSubst(t.Value)
	case *ast.ChanType:
		return "chan " + exprToStringNoSubst(t.Value)
	case *ast.FuncType:
		return "func()" // simplified
	default:
		return "string"
	}
}

