	if isExported(name) {
		return "Test" + name
	}
	return "Test_" + name
}

func testNameForMethod(recvType, method string) string {
	// recvType is base type name without * and without type params, e.g., "T", "t2", "Set", "MyInt"
	prefix := ""
	if isExported(recvType) {
		prefix = "Test" + recvType
	} else {
		prefix = "Test_" + recvType
	}
