}

// concreteForConstraint returns concrete type string for a type param constraint
func concreteForConstraint(expr ast.Expr) string {
	switch t := expr.(type) {
	case *ast.Ident:
		if t.Name == "any" {
			return "int"
		}
		if t.Name == "comparable" {
			return "string"
		}
		if t.Name == "Ordered" {
			return "int"
		}
		return "string"
	case *ast.SelectorExpr:
		if t.Sel != nil && t.Sel.Name == "Ordered" {
			return "int"
		}
		return "string"
	case *ast.UnaryExpr:
		// ~T
		return exprToString(t.X, nil)
	case *ast.BinaryExpr:
		// union A | B : take leftmost
		left := t.X
		for {
			if b, ok := left.(*ast.BinaryExpr); ok {
				// check op is |
				if b.Op.String() == "|" {
					left = b.X
					continue
				}
			}
			break
		}
		if u, ok := left.(*ast.UnaryExpr); ok {
			return exprToString(u.X, nil)
		}
		return exprToString(left, nil)
	case *ast.InterfaceType:
		// For interface with union inside? Try to find union?
		// If interface has methods with union, take first?
		// For simplicity, return "string"
		// Check if interface has embedded union like ~int|~string?
		// Look at Methods list
		if t.Methods != nil {
			for _, f := range t.Methods.List {
				// f.Type could be union or ~?
				// If it's union, take leftmost
				if b, ok := f.Type.(*ast.BinaryExpr); ok {
					left := b.X
					for {
						if bb, ok := left.(*ast.BinaryExpr); ok {
							left = bb.X
							continue
						}
						break
					}
					if u, ok := left.(*ast.UnaryExpr); ok {
						return exprToString(u.X, nil)
					}
					return exprToString(left, nil)
				}
				if u, ok := f.Type.(*ast.UnaryExpr); ok {
					return exprToString(u.X, nil)
				}
			}
		}
		return "string"
	default:
		return "string"
	}
}

func exprToString(expr ast.Expr, typeMap map[string]string) string {
	if expr == nil {
		return ""
	}
	switch t := expr.(type) {
	case *ast.Ident:
		if typeMap != nil {
			if v, ok := typeMap[t.Name]; ok {
				return v
			}
		}
		return t.Name
	case *ast.SelectorExpr:
		return exprToString(t.X, typeMap) + "." + t.Sel.Name
	case *ast.StarExpr:
		return "*" + exprToString(t.X, typeMap)
	case *ast.ArrayType:
		if t.Len == nil {
			return "[]" + exprToString(t.Elt, typeMap)
		}
		// Array length could be expr like 3 or ...? For [3]int, Len is BasicLit "3"
		lenStr := exprToString(t.Len, typeMap)
		return "[" + lenStr + "]" + exprToString(t.Elt, typeMap)
	case *ast.MapType:
		return "map[" + exprToString(t.Key, typeMap) + "]" + exprToString(t.Value, typeMap)
	case *ast.ChanType:
		// Need dir? chan, <-chan, chan<-
		switch t.Dir {
		case ast.SEND:
			return "chan<- " + exprToString(t.Value, typeMap)
		case ast.RECV:
			return "<-chan " + exprToString(t.Value, typeMap)
		default:
			return "chan " + exprToString(t.Value, typeMap)
		}
	case *ast.FuncType:
		// func(params) results
		return funcTypeToString(t, typeMap)
	case *ast.InterfaceType:
		if t.Methods == nil || len(t.Methods.List) == 0 {
			return "interface{}"
		}
		// For interface with methods, need to print? e.g., interface{ Foo() }? But for our purposes (params/results types like io.Reader?), the type string is like "io.Reader" (selector), not interface literal.
		// Interface literal as type (e.g., struct{ X int }? No, that's struct. For interface literal like interface{ M() } as param type? Unlikely, but handle.
		// Simplify: if single method? Return "interface{...}"? Actually for empty interface{} we already handled. For non-empty, return as is via printer? Use fallback.
		// To avoid complexity, return "interface{}" for non-empty? No, that would be wrong for struct? Wait struct is StructType, not Interface.
		// For interface with methods, the type string in source is like "interface{ Foo() }"? But our earlier test with "interface{}" as param? That was `func F(a interface{})`? Actually `interface{}` is empty. For `io.Reader` it's selector, not interface literal.
		// So this case rarely used. Return "interface{}" for simplicity? But need to handle `any`? `any` is Ident, not Interface.
		return "interface{}"
	case *ast.StructType:
		// struct{ X int } etc.
		if t.Fields == nil || len(t.Fields.List) == 0 {
			return "struct{}"
		}
		var parts []string
		for _, f := range t.Fields.List {
			typeStr := exprToString(f.Type, typeMap)
			if len(f.Names) == 0 {
				// Embedded? e.g., Inner
				parts = append(parts, typeStr)
			} else {
				for _, n := range f.Names {
					parts = append(parts, n.Name+" "+typeStr)
				}
			}
		}
		return "struct{ " + strings.Join(parts, "; ") + " }"
	case *ast.Ellipsis:
		return "[]" + exprToString(t.Elt, typeMap)
	case *ast.BasicLit:
		return t.Value
	case *ast.ParenExpr:
		return exprToString(t.X, typeMap)
	case *ast.IndexExpr:
		// Generic instantiation like Set[string]? Actually for type strings with generics? e.g., T? No, for our substitution, type params are replaced, so IndexExpr shouldn't appear in final? But for constraint like My[T]? Hmm.
		return exprToString(t.X, typeMap) + "[" + exprToString(t.Index, typeMap) + "]"
	case *ast.IndexListExpr:
		var parts []string
		for _, e := range t.Indices {
