{"command": "cat > /workspace/gen_core.go <<'GOEOF'
package main

import (
	"go/ast"
	"go/token"
	"regexp"
	"strings"
)

type Param struct {
	Name string
	TypeStr string
	TypeAST ast.Expr
	IsVariadic bool
}

type Result struct {
	Name string
	TypeStr string
	TypeAST ast.Expr
	IsError bool
	WantName string
	GotName string
	NeedsDeepEqual bool
}

type FuncInfo struct {
	Name string
	IsMethod bool
	RecvName string // as in source, e.g., "t", "s", "_", ""
	RecvType string // base, e.g., "T", "Set"
	RecvTypeAST ast.Expr
	RecvIsPointer bool
	RecvTypeParamsStr string // e.g., "[string]" for generic? Actually for instantiation
	TestName string
	Params []Param
	Results []Result // non-error results only? Actually all non-error? Error separate
	HasError bool
	TypeParams []string
	TypeMap map[string]string
	Fields []Field
	HasFields bool
	DirectName string
	DirectType string
	Decl *ast.FuncDecl
}

type Field struct {
	Name string
	TypeStr string
	TypeAST ast.Expr
}

func extractFuncs(srcFile *ast.File, otherFiles map[string]*ast.File, fset *token.FileSet, isTestFile bool, onlyRe, exclRe *regexp.Regexp, exportedOnly bool) []FuncInfo {
	var out []FuncInfo
	for _, decl := range srcFile.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		name := fd.Name.Name
		// Skip Test* in test files
		if isTestFile && strings.HasPrefix(name, "Test") {
			continue
		}
		isMethod := fd.Recv != nil && len(fd.Recv.List) > 0
		var recvName string
		var recvTypeAST ast.Expr
		var recvTypeBase string
		var recvIsPtr bool
		if isMethod {
			rf := fd.Recv.List[0]
			if len(rf.Names) > 0 {
				recvName = rf.Names[0].Name
			}
			recvTypeAST = rf.Type
			recvTypeBase, recvIsPtr = baseTypeName(rf.Type)
		}
		// Filtering
		if exportedOnly {
			if !isExported(name) {
				continue
			}
		}
		if onlyRe != nil {
			if !matchesWithTitle(onlyRe, recvTypeBase, name, isMethod) {
				continue
			}
		}
		if exclRe != nil {
			if matchesWithTitle(exclRe, recvTypeBase, name, isMethod) {
				continue
			}
		}
		// Build FuncInfo (params, results, etc. will be filled later)
		fi := FuncInfo{
			Name: name,
			IsMethod: isMethod,
			RecvName: recvName,
			RecvType: recvTypeBase,
			RecvTypeAST: recvTypeAST,
			RecvIsPointer: recvIsPtr,
			Decl: fd,
		}
		if isMethod {
			fi.TestName = testNameForMethod(recvTypeBase, name)
		} else {
			fi.TestName = testNameForFunc(name)
		}
		out = append(out, fi)
	}
	return out
}

func baseTypeName(expr ast.Expr) (string, bool) {
