func fillFuncDetails(fi *FuncInfo, srcFile *ast.File, otherFiles map[string]*ast.File) {
	fd := fi.Decl
	// Type params for func
	typeMap := make(map[string]string)
	var typeParamNames []string
	if fd.Type.TypeParams != nil {
		for _, f := range fd.Type.TypeParams.List {
			concrete := concreteForConstraint(f.Type)
			for _, n := range f.Names {
				typeMap[n.Name] = concrete
				typeParamNames = append(typeParamNames, n.Name)
			}
			// Handle case with no names? e.g., func Foo[T any] has names, but func Foo[any]? Unlikely (must have names). Ignore.
		}
	}
	// For methods on generic types, need receiver type params
	// Find struct definition for recv type
	if fi.IsMethod {
		recvBase := fi.RecvType
		// Find TypeSpec with that name in srcFile + otherFiles
		ts := findTypeSpec(recvBase, srcFile, otherFiles)
		if ts != nil && ts.TypeParams != nil {
			for _, f := range ts.TypeParams.List {
				concrete := concreteForConstraint(f.Type)
				for _, n := range f.Names {
					// Only add if not already in typeMap (func type params take precedence? Actually receiver T and func T could conflict? Unlikely)
					if _, ok := typeMap[n.Name]; !ok {
						typeMap[n.Name] = concrete
						// Don't add to typeParamNames? For instantiation, need both func and recv type params?
						// For receiver instantiation, need recv type params; for func call, need func type params + recv? Actually call is like Foo[int] for func, and receiver is My[int] for method.
						// For method on generic type with no func type params, call has no [..], but receiver has [..].
						// For generic func, call has [..].
						// So we need to keep them separate? Simplify: typeMap contains all, and TypeParams for func only for call instantiation?
						// For receiver instantiation, need recv type params mapping separately.
					}
				}
			}
			// Store recv type param mapping for later? For now, typeMap has all.
		}
	}
	fi.TypeMap = typeMap
	fi.TypeParams = typeParamNames

	// Params
	var params []Param
	paramIndex := 0
	if fd.Type.Params != nil {
		for _, field := range fd.Type.Params.List {
			isVariadic := false
			var baseType ast.Expr = field.Type
			if ell, ok := field.Type.(*ast.Ellipsis); ok {
				isVariadic = true
				baseType = ell.Elt
			}
			typeStr := exprToString(baseType, typeMap)
			if isVariadic {
				// For args struct, type is []T, not ...T
				typeStr = "[]" + exprToString(baseType, typeMap)
				// Actually baseType is Elt, so []Elt
				// Our exprToString for Ellipsis already gives []Elt, but we handled separately. Good.
			}
			if len(field.Names) == 0 {
				// Unnamed param? e.g., func F(int, string)? Then need in0, in1?
				// Actually for params, unnamed means no name, need in<index>?
				// Test: func F(int, string)? Let's check original: likely in0, in1.
				// We'll handle: single unnamed field with no names -> one param with in<index>
				params = append(params, Param{Name: sprintfIn(paramIndex), TypeStr: typeStr, TypeAST: baseType, IsVariadic: isVariadic})
				paramIndex++
			} else {
				for _, n := range field.Names {
					name := n.Name
					if name == "_" || name == "" {
						name = sprintfIn(paramIndex)
					}
					params = append(params, Param{Name: name, TypeStr: typeStr, TypeAST: baseType, IsVariadic: isVariadic})
					paramIndex++
				}
			}
		}
	}
	fi.Params = params

	// Results
	// Expand grouped results
	type rawResult struct {
		Name string
		TypeAST ast.Expr
	}
	var raws []rawResult
	if fd.Type.Results != nil {
		for _, field := range fd.Type.Results.List {
			if len(field.Names) == 0 {
				raws = append(raws, rawResult{Name: "", TypeAST: field.Type})
			} else {
				// Check if this field is actually grouped? e.g., (x, y int) has Names=[x,y] Type=int -> two results
				// But also (int, y string) has? Actually parser groups (int, y string) as one field with Names=[int,y] Type=string? That's weird but we handle as grouped.
				// For (x int, y string) with two fields each with one name, each is separate.
				for _, n := range field.Names {
					raws = append(raws, rawResult{Name: n.Name, TypeAST: field.Type})
				}
			}
		}
	}
	// Determine error: if any result IsError (exactly "error"), then HasError = true, and that result is excluded from wants (collapsed to single wantErr)
	// If multiple errors, still single wantErr (as observed)
	hasError := false
	for _, r := range raws {
		if isErrorType(r.TypeAST) {
			hasError = true
			break
		}
	}
	fi.HasError = hasError
	// Build non-error results with Want/Got naming
	var nonErrRaws []rawResult
	for _, r := range raws {
		if isErrorType(r.TypeAST) {
			continue
		}
		nonErrRaws = append(nonErrRaws, r)
	}
	// If hasError and all results are errors (e.g., (error, error)), then nonErr is empty, HasError true, no wants
	// Naming for wants/gots
	var results []Result
	if len(nonErrRaws) == 1 && len(raws) == 1 {
		// Single result, single field (could be named or unnamed)
		r := nonErrRaws[0]
		origName := r.Name
		var wantName, gotName string
		if origName == "" || origName == "_" {
			wantName = "want"
			gotName = "got"
		} else {
			wantName = "want" + titleStr(origName)
			gotName = "got" + titleStr(origName)
		}
		typeStr := exprToString(r.TypeAST, typeMap)
		needsDeep := needsDeepEqualForResult(r.TypeAST, typeMap, fi)
		results = append(results, Result{Name: origName, TypeStr: typeStr, TypeAST: r.TypeAST, IsError: false, WantName: wantName, GotName: gotName, NeedsDeepEqual: needsDeep})
	} else if len(nonErrRaws) > 0 {
		// Multiple (or single with multiple? Actually single named with multiple? No, len(nonErrRaws)==1 but len(raws)>1 means single non-error + error(s)? e.g., (int, error) has nonErr=1, raws=2. Then naming? For (int, error) with single non-error unnamed, want should be "want" (not "wantX")? Observed (string, error) with unnamed gives "want" (not "want0")? Yes, for (string, error) single non-error, want is "want" (as in earlier (string,error) test: want string, not want0). Good. So for single non-error + error, use single naming (want/got).
		// For multiple non-errors, use want/want1... or wantX...
		if len(nonErrRaws) == 1 && hasError {
			r := nonErrRaws[0]
			origName := r.Name
			var wantName, gotName string
			if origName == "" || origName == "_" {
				wantName = "want"
				gotName = "got"
			} else {
				wantName = "want" + titleStr(origName)
				gotName = "got" + titleStr(origName)
			}
			typeStr := exprToString(r.TypeAST, typeMap)
			needsDeep := needsDeepEqualForResult(r.TypeAST, typeMap, fi)
			results = append(results, Result{Name: origName, TypeStr: typeStr, TypeAST: r.TypeAST, IsError: false, WantName: wantName, GotName: gotName, NeedsDeepEqual: needsDeep})
		} else {
			// Multiple non-errors
			// Check if any have names? If all unnamed (or _), use want, want1, want2... and got, got1...
			// If any named, use wantX for named and wantInt? Actually for mixed? Earlier (int, y string) grouped as names [int,y] both named? That gave wantInt, wantY. So for named, use want+Title(name).
			// For unnamed in multi, use want, want1...? But what about mixed named+unnamed? In Go, you can't have mixed like (x int, string) is invalid (missing type). Actually (x int, string) would be parsed as? The second field has no name, first has name? That's two fields: first Names=[x] Type=int, second Names=[] Type=string. That's valid? `func F() (x int, string)`? Is that valid Go? Let's see: results (x int, string) means first named x int, second unnamed string. That's valid. How would naming be? First wantX, second want1? Or want, want1? Need to test, but unlikely.
			// Simplify: for each nonErr in order, if Name is "" or "_" then use want/want1... (with index among unnamed? Or overall? Observed for (int, int) both unnamed: want, want1 (first want, second want1). Good (overall index, first is want, rest wantN where N is overall index? For 3 returns (int,string,bool) all unnamed: want, want1, want2 (as observed). Good (N is position: 0->want, 1->want1, 2->want2).
			// For named, use want+Title(name) (e.g., x->wantX). Good.
			for idx, r := range nonErrRaws {
				origName := r.Name
				var wantName, gotName string
				if origName == "" || origName == "_" {
					if idx == 0 {
						wantName = "want"
						gotName = "got"
					} else {
						wantName = sprintfWant(idx)
						gotName = sprintfGot(idx)
					}
				} else {
					// Named: check if name is "_" ? Already handled. Else want+Title
					// But what about name "int" (keyword as name)? For (int, y string) grouped, first name is "int" (keyword). Title("int") = "Int", so wantInt. Good.
					wantName = "want" + titleStr(origName)
					gotName = "got" + titleStr(origName)
				}
				typeStr := exprToString(r.TypeAST, typeMap)
				needsDeep := needsDeepEqualForResult(r.TypeAST, typeMap, fi)
				results = append(results, Result{Name: origName, TypeStr: typeStr, TypeAST: r.TypeAST, IsError: false, WantName: wantName, GotName: gotName, NeedsDeepEqual: needsDeep})
			}
			// Special case: for unnamed multi, first is want, rest want1... But what about named+unnamed mix where first is named? Example: (x int, string) with first named x, second unnamed. Then first wantX, second want1? Or want1? Our code gives second want1 (since idx=1 -> want1). Good. But should second be want1 or want? The overall index logic (idx) gives want1 for second, which seems reasonable. Need to verify with actual? Unlikely tested.
		}
	}
	fi.Results = results

	// Receiver fields / direct
	if fi.IsMethod {
		// Find struct fields if receiver is struct
		recvBase := fi.RecvType
		ts := findTypeSpec(recvBase, srcFile, otherFiles)
		isStruct := false
		var fields []Field
		if ts != nil {
			if st, ok := ts.Type.(*ast.StructType); ok {
				isStruct = true
				if st.Fields != nil {
					for _, f := range st.Fields.List {
