							embName := exprToString(f.Type, nil) // without substitution? For embedded Inner (no generics), same
							// For embedded with package? e.g., *bytes.Buffer? Unlikely. Use base?
							// Use type string as name? For Inner (Ident), name is Inner
							// For *Inner? Name?
							fields = append(fields, Field{Name: embName, TypeStr: typeStr, TypeAST: f.Type})
							// Actually for embedded *T? Name should be T? Hmm. Simplify: use base?
						} else {
							for _, n := range f.Names {
								fields = append(fields, Field{Name: n.Name, TypeStr: typeStr, TypeAST: f.Type})
							}
						}
					}
				}
			}
		}
		// Check if generic receiver (has type params in struct definition or receiver type has Index?)
		isGenericRecv := false
		if ts != nil && ts.TypeParams != nil && len(ts.TypeParams.List) > 0 {
			isGenericRecv = true
		}
		// Also if receiver type AST is Index (e.g., Set[T])? That's generic
		// For generic, always use direct (no fields), even if struct has fields (as observed for Box with Value, still direct)
		if isGenericRecv {
			fi.HasFields = false
			// Direct
			recvVar := receiverVarName(fi.RecvName, fi.RecvType)
			// Direct type is recv base with concrete params, e.g., Set[string], My[int], Box[int]
			// Need to determine concrete params for recv: look at struct's type params and typeMap
			var concretes []string
			if ts != nil && ts.TypeParams != nil {
				for _, f := range ts.TypeParams.List {
					c := concreteForConstraint(f.Type)
					for range f.Names {
						concretes = append(concretes, c)
					}
				}
			}
			recvTypeWithParams := recvBase
			if len(concretes) > 0 {
				recvTypeWithParams = recvBase + "[" + joinStrings(concretes, ", ") + "]"
			}
			if fi.RecvIsPointer {
				recvTypeWithParams = "*" + recvTypeWithParams
			}
			fi.DirectName = recvVar
			fi.DirectType = recvTypeWithParams
		} else if isStruct && len(fields) > 0 {
			fi.HasFields = true
			fi.Fields = fields
		} else {
			// No fields or not struct: direct
			fi.HasFields = false
			recvVar := receiverVarName(fi.RecvName, fi.RecvType)
			recvTypeStr := recvBase
			if fi.RecvIsPointer {
				recvTypeStr = "*" + recvTypeStr
			}
			fi.DirectName = recvVar
			fi.DirectType = recvTypeStr
		}
	}
}

func sprintfIn(i int) string {
	return "in" + itoa(i)
}

func sprintfWant(i int) string {
	if i == 0 {
		return "want"
	}
	return "want" + itoa(i)
}

func sprintfGot(i int) string {
	if i == 0 {
		return "got"
	}
	return "got" + itoa(i)
}

func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	s := ""
	for i > 0 {
		s = string(rune('0'+i%10)) + s
		i /= 10
	}
	return s
}

func joinStrings(a []string, sep string) string {
	s := ""
	for i, v := range a {
		if i > 0 {
			s += sep
		}
		s += v
	}
	return s
}

func titleStr(s string) string {
	if s == "" {
		return ""
	}
	b := s[0]
	if b >= 'a' && b <= 'z' {
		return string(b-32) + s[1:]
	}
	return s
}

func receiverVarName(recvName, recvType string) string {
