func sprintfIn(i int) string {
	return "in" + itoa(i)
}

func sprintfWant(i int) string {
	if i == 0 {
		return "want"
	}
	return "want" + itoa(i)
}

func sprintfGot(i int) string {
	if i == 0 {
		return "got"
	}
	return "got" + itoa(i)
}

func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	s := ""
	for i > 0 {
		s = string(rune('0'+i%10)) + s
		i /= 10
	}
	return s
}

func joinStrings(a []string, sep string) string {
	s := ""
	for i, v := range a {
		if i > 0 {
			s += sep
		}
		s += v
	}
	return s
}

func titleStr(s string) string {
	if s == "" {
		return ""
	}
	b := s[0]
	if b >= 'a' && b <= 'z' {
		return string(b-32) + s[1:]
	}
	return s
}

