		}
		return fi.Name + "[" + strings.Join(concretes, ", ") + "]"
	}
	return fi.Name
}

func fullMethodNameForError(fi FuncInfo) string {
	// For error messages: "T.Foo" or "My[T].Foo"? Actually for generic, observed "My[T].Foo" (with T, not concrete)? Let's see: earlier generic My with Foo gave "My[T].Foo" (with T, not int). Yes, for TestMy_Foo with generic, error message was "My[T].Foo() ..." (with [T], not [int]).
	// For non-generic, "T.Foo" or "MyStruct.Method" etc.
	if fi.IsGenericRecv {
		return fi.RecvType + "[T]." + fi.Name
	}
	if fi.IsMethod {
		return fi.RecvType + "." + fi.Name
	}
	return fi.Name
}

