func generateBodySubtests(fi FuncInfo, iFlag, useGoCmpFlag bool) string {
	var sb strings.Builder
	indent := "\t\t\t"
	// Receiver creation
	recvVar := ""
	recvCreate := ""
	if fi.IsMethod {
		if fi.HasFields {
			recvVar = receiverVarName(fi.RecvName, fi.RecvType)
			amp := ""
			if fi.RecvIsPointer {
				amp = "&"
			}
			sb.WriteString(indent + recvVar + " := " + amp + fi.RecvType + "{\n")
			for _, f := range fi.Fields {
				sb.WriteString(indent + "\t" + f.Name + ": tt.fields." + f.Name + ",\n")
			}
			sb.WriteString(indent + "}\n")
		} else {
			// Direct
			if fi.IsStructRecv {
				// Struct (including generic struct) with no fields: create empty, ignore tt
				recvVar = fi.DirectName
				// DirectType already includes * and [..] if needed, but for creation need base without *? Actually s := &Set[string]{} vs tr := T{}.
				// For pointer, amp is part of DirectType? DirectType is "*Set[string]" or "*T" or "T", etc.
				// Creation is: recvVar := DirectType{}? But DirectType has * for pointer, need &?
				// For *T, DirectType is "*T", creation is "recvVar := &T{}" (with & and base without *). For T, "recvVar := T{}".
				// For *Set[string], DirectType "*Set[string]", creation "&Set[string]{}".
				// So need base without *.
				base := strings.TrimPrefix(fi.DirectType, "*")
				amp := ""
				if strings.HasPrefix(fi.DirectType, "*") {
					amp = "&"
				}
				sb.WriteString(indent + recvVar + " := " + amp + base + "{}\n")
			} else {
				// Non-struct: no creation, use tt.DirectName directly later
				recvVar = ""
			}
		}
	}
	// Build call
	call := buildCall(fi, recvVar)
	// Handle results
	if len(fi.Results) == 0 && !fi.HasError {
		// Void
		sb.WriteString(indent + call + "\n")
		return sb.String()
	}
	if len(fi.Results) == 0 && fi.HasError {
		// Error only
		// if err := Foo(...); (err != nil) != tt.wantErr { t.Errorf(...) }
		errVar := "err"
		assign := "if " + errVar + " := " + call + "; "
		cond := "(" + errVar + " != nil) != tt.wantErr"
		msg, args := errorMsg(fi, iFlag, true, false)
		sb.WriteString(indent + assign + cond + " {\n")
		sb.WriteString(indent + "\t" + msg + "\n")
		sb.WriteString(indent + "}\n")
		_ = args
		return sb.String()
	}
	if len(fi.Results) == 1 && !fi.HasError {
		// Single non-error
		r := fi.Results[0]
		got := r.GotName
		want := "tt." + r.WantName
		assign := "if " + got + " := " + call + "; "
		var cond, msg string
		if r.NeedsDeepEqual {
			if useGoCmpFlag {
				cond = "!cmp.Equal(" + want + ", " + got + ")"
				msg = cmpMsg(fi, iFlag, got, want)
			} else {
				cond = "!reflect.DeepEqual(" + got + ", " + want + ")"
				msg = deepEqualMsg(fi, iFlag, got, want)
			}
		} else {
			cond = got + " != " + want
			msg = equalMsg(fi, iFlag, got, want)
		}
		sb.WriteString(indent + assign + cond + " {\n")
