		return sb.String()
	}
	if len(fi.Results) > 1 && fi.HasError {
		// Multiple non-errors + error: got, got1, err := Foo(...); if (err != nil) != wantErr { Fatalf } if wantErr { return } if got != want ...
		var gots []string
		for _, r := range fi.Results {
			gots = append(gots, r.GotName)
		}
		gots = append(gots, "err")
		sb.WriteString(indent + strings.Join(gots, ", ") + " := " + call + "\n")
		sb.WriteString(indent + "if (err != nil) != tt.wantErr {\n")
		sb.WriteString(indent + "\t" + errorFatalMsg(fi, iFlag) + "\n")
		sb.WriteString(indent + "}\n")
		sb.WriteString(indent + "if tt.wantErr {\n")
		sb.WriteString(indent + "\treturn\n")
		sb.WriteString(indent + "}\n")
		for _, r := range fi.Results {
			got := r.GotName
			want := "tt." + r.WantName
			var cond, msg string
			if r.NeedsDeepEqual {
				if useGoCmpFlag {
					cond = "!cmp.Equal(" + want + ", " + got + ")"
					msg = cmpMsgMulti(fi, iFlag, got, want, r)
				} else {
					cond = "!reflect.DeepEqual(" + got + ", " + want + ")"
					msg = deepEqualMsgMulti(fi, iFlag, got, want, r)
				}
			} else {
				cond = got + " != " + want
				msg = equalMsgMulti(fi, iFlag, got, want, r)
			}
			sb.WriteString(indent + "if " + cond + " {\n")
			sb.WriteString(indent + "\t" + msg + "\n")
			sb.WriteString(indent + "}\n")
		}
		return sb.String()
	}
	return sb.String()
}

func buildCall(fi FuncInfo, recvVar string) string {
	args := argsList(fi)
	// Determine func/method name with type params
	if !fi.IsMethod {
		name := fi.Name
		if len(fi.TypeParams) > 0 {
			var concretes []string
			for _, tp := range fi.TypeParams {
				concretes = append(concretes, fi.TypeMap[tp])
			}
			name += "[" + strings.Join(concretes, ", ") + "]"
		}
		if args == "" {
			return name + "()"
		}
		return name + "(" + args + ")"
	}
	// Method
	mName := fi.Name
	if len(fi.TypeParams) > 0 {
		// Method has own type params? Use them (but TypeParams includes only func's, which for method with own generics is correct)
		// However for method on generic type, TypeParams is empty (since no func type params), so no instantiation here (receiver already instantiated)
		// For method with own type params (e.g., Foo[U]), need instantiation
		// But how to distinguish recv generic vs method generic? Our TypeParams only has func's, so for method on generic with no func params, len==0, no instantiation. Good.
		// For method with own params, len>0, instantiate.
		// But what about method on generic where func has no params but recv does? TypeParams empty, so no instantiation. Good.
		var concretes []string
		for _, tp := range fi.TypeParams {
			concretes = append(concretes, fi.TypeMap[tp])
		}
		mName += "[" + strings.Join(concretes, ", ") + "]"
	}
	var recv string
	if fi.HasFields {
		recv = recvVar
	} else {
		if fi.IsStructRecv || fi.IsGenericRecv {
			recv = recvVar
		} else {
			// Non-struct direct: tt.DirectName
			recv = "tt." + fi.DirectName
		}
	}
	if args == "" {
		return recv + "." + mName + "()"
	}
	return recv + "." + mName + "(" + args + ")"
}

