{"command": "cat > /workspace/messages.go <<'GOEOF'
package main

import (
	"strings"
)

func methodPrefix(fi FuncInfo) string {
	if fi.IsMethod {
		if fi.IsGenericRecv {
			return fi.RecvType + "[T]." + fi.Name
		}
		return fi.RecvType + "." + fi.Name
	}
	return fi.Name
}

func callInputs(fi FuncInfo, iFlag bool) (placeholders, values string) {
	if !iFlag || len(fi.Params) == 0 {
		return "", ""
	}
	var ph []string
	var vals []string
	for _, p := range fi.Params {
		ph = append(ph, "%v")
		vals = append(vals, "tt.args."+p.Name)
	}
	return strings.Join(ph, ", "), strings.Join(vals, ", ")
}

func errorMsg(fi FuncInfo, iFlag bool, isSingleError bool) string {
	// For subtests, single error or error part of (T,error)? Actually single error uses Errorf, (T,error) error part uses Fatalf.
	// This helper for single error only (Errorf)
	prefix := methodPrefix(fi)
	ph, vals := callInputs(fi, iFlag)
	callStr := prefix + "()"
	if ph != "" {
		callStr = prefix + "(" + ph + ")"
	}
	// Message: t.Errorf("Add() error = %v, wantErr %v", err, tt.wantErr) or with inputs: t.Errorf("Add(%v) error = %v, wantErr %v", tt.args.a, err, tt.wantErr)
	if ph == "" {
		return `t.Errorf("` + callStr + ` error = %v, wantErr %v", err, tt.wantErr)`
	}
	return `t.Errorf("` + callStr + ` error = %v, wantErr %v", ` + vals + `, err, tt.wantErr)`
}

func errorFatalMsg(fi FuncInfo, iFlag bool) string {
	prefix := methodPrefix(fi)
	ph, vals := callInputs(fi, iFlag)
	callStr := prefix + "()"
	if ph != "" {
		callStr = prefix + "(" + ph + ")"
	}
	if ph == "" {
		return `t.Fatalf("` + callStr + ` error = %v, wantErr %v", err, tt.wantErr)`
	}
	return `t.Fatalf("` + callStr + ` error = %v, wantErr %v", ` + vals + `, err, tt.wantErr)`
}

func equalMsg(fi FuncInfo, iFlag bool, got, want string) string {
	prefix := methodPrefix(fi)
	ph, vals := callInputs(fi, iFlag)
	callStr := prefix + "()"
	if ph != "" {
		callStr = prefix + "(" + ph + ")"
	}
	if ph == "" {
		return `t.Errorf("` + callStr + ` = %v, want %v", ` + got + `, ` + want + `)`
	}
	return `t.Errorf("` + callStr + ` = %v, want %v", ` + vals + `, ` + got + `, ` + want + `)`
}

func deepEqualMsg(fi FuncInfo, iFlag bool, got, want string) string {
	return equalMsg(fi, iFlag, got, want)
}

func cmpMsg(fi FuncInfo, iFlag bool, got, want string) string {
	prefix := methodPrefix(fi)
	ph, vals := callInputs(fi, iFlag)
	callStr := prefix + "()"
	if ph != "" {
		callStr = prefix + "(" + ph + ")"
