func buildCall(fi FuncInfo, recvVar string) string {
	args := argsList(fi)
	if !fi.IsMethod {
		name := fi.Name
		if len(fi.TypeParams) > 0 {
			var concretes []string
			for _, tp := range fi.TypeParams {
				concretes = append(concretes, fi.TypeMap[tp])
			}
			name += "[" + strings.Join(concretes, ", ") + "]"
		}
		if args == "" {
			return name + "()"
		}
		return name + "(" + args + ")"
	}
	mName := fi.Name
	if len(fi.TypeParams) > 0 {
		var concretes []string
		for _, tp := range fi.TypeParams {
			concretes = append(concretes, fi.TypeMap[tp])
		}
		// For methods on generic types, TypeParams is empty (since no func type params), so no instantiation here.
		// Only if method has own type params (len>0) then instantiate. But our TypeParams includes only func's, so correct.
		// However need to check: if method on generic with no func params, TypeParams empty, so no instantiation. Good.
		// If method has own params, instantiate.
		if len(concretes) > 0 {
			// Check if concretes correspond to func type params or recv? For method on generic with func params, TypeParams has func's, correct.
			// But what about generic recv with no func params? TypeParams empty, so no instantiation. Good.
			mName += "[" + strings.Join(concretes, ", ") + "]"
		}
	}
	var recv string
	if fi.HasFields {
		recv = recvVar
	} else {
		if fi.IsStructRecv || fi.IsGenericRecv {
			recv = recvVar
		} else {
			recv = "tt." + fi.DirectName
		}
	}
	if args == "" {
		return recv + "." + mName + "()"
	}
	return recv + "." + mName + "(" + args + ")"
}

func argsList(fi FuncInfo) string {
	var parts []string
	for _, p := range fi.Params {
		arg := "tt.args." + p.Name
		if p.IsVariadic {
			arg += "..."
		}
		parts = append(parts, arg)
	}
	return strings.Join(parts, ", ")
}

