			// But what about generic recv with no func params? TypeParams empty, so no instantiation. Good.
			mName += "[" + strings.Join(concretes, ", ") + "]"
		}
	}
	var recv string
	if fi.HasFields {
		recv = recvVar
	} else {
		if fi.IsStructRecv || fi.IsGenericRecv {
			recv = recvVar
		} else {
			recv = "tt." + fi.DirectName
		}
	}
	if args == "" {
		return recv + "." + mName + "()"
	}
	return recv + "." + mName + "(" + args + ")"
}

func argsList(fi FuncInfo) string {
	var parts []string
	for _, p := range fi.Params {
		arg := "tt.args." + p.Name
		if p.IsVariadic {
			arg += "..."
		}
		parts = append(parts, arg)
	}
	return strings.Join(parts, ", ")
}

func generateBodyNoSubtests(fi FuncInfo, iFlag bool, namedFlag bool, useGoCmpFlag bool) string {
	var sb strings.Builder
	indent := "\t\t"
	// Receiver creation (without t.Run, so indent is \t\t, not \t\t\t)
	if fi.IsMethod {
		if fi.HasFields {
			recvVar := receiverVarName(fi.RecvName, fi.RecvType)
			amp := ""
			if fi.RecvIsPointer {
				amp = "&"
			}
			sb.WriteString(indent + recvVar + " := " + amp + fi.RecvType + "{\n")
			for _, f := range fi.Fields {
				sb.WriteString(indent + "\t" + f.Name + ": tt.fields." + f.Name + ",\n")
			}
			sb.WriteString(indent + "}\n")
		} else {
			if fi.IsStructRecv || fi.IsGenericRecv {
				recvVar := fi.DirectName
				base := strings.TrimPrefix(fi.DirectType, "*")
				amp := ""
				if strings.HasPrefix(fi.DirectType, "*") {
					amp = "&"
				}
				// For nosubtests with named, need to use tt? Actually creation doesn't use tt for struct empty (ignores tt), same as subtests.
				// For nosubtests, creation is outside t.Run, at same indent \t\t
				sb.WriteString(indent + recvVar + " := " + amp + base + "{}\n")
			}
		}
	}
	// Build call with appropriate recv
	recvVar := ""
	if fi.IsMethod {
		if fi.HasFields {
			recvVar = receiverVarName(fi.RecvName, fi.RecvType)
		} else {
			if fi.IsStructRecv || fi.IsGenericRecv {
				recvVar = fi.DirectName
			} else {
				recvVar = ""
			}
		}
	}
	call := buildCallNoSub(fi, recvVar, namedFlag)
	// Handle results for nosubtests (with "%q. " prefix and continue/return)
	if len(fi.Results) == 0 && !fi.HasError {
		// Void: need to handle loop var? For nosubtests void with "for range" (no tt), call is Foo() without tt? Actually for void with no args, call is Foo() (no tt). Good.
		// For void with args (e.g., F(a int) void), call is F(tt.args.a) (needs tt, loop has tt). Good.
		sb.WriteString(indent + call + "\n")
		return sb.String()
	}
	if len(fi.Results) == 0 && fi.HasError {
		// Error only with nosubtests: for range bug? Loop is "for range" but body uses tt? We'll generate with tt (bug replicate)
		// if err := Foo(); (err != nil) != tt.wantErr { t.Errorf(...)}
		// For named, use name instead of tt.name in message, and loop is "for range" (bug, uses name, tt undefined)
		msg := errorMsgNoSub(fi, iFlag, namedFlag)
		// Need to determine assign: if has params, call with tt.args, else without
		sb.WriteString(indent + "if err := " + call + "; (err != nil) != tt.wantErr {\n")
		sb.WriteString(indent + "\t" + msg + "\n")
		sb.WriteString(indent + "}\n")
		return sb.String()
	}
	if len(fi.Results) == 1 && !fi.HasError {
		r := fi.Results[0]
		got := r.GotName
		want := "tt." + r.WantName
		var cond, msg string
		if r.NeedsDeepEqual {
			if useGoCmpFlag {
				cond = "!cmp.Equal(" + want + ", " + got + ")"
				msg = cmpMsgNoSub(fi, iFlag, namedFlag, got, want)
			} else {
				cond = "!reflect.DeepEqual(" + got + ", " + want + ")"
				// For nosubtests, deepEqual message is same as equal but with DeepEqual condition? Message same as equal (without diff for standard? Actually standard DeepEqual message is same as equal: "Add() = %v, want %v")
				msg = equalMsgNoSub(fi, iFlag, namedFlag, got, want)
				// Need to handle DeepEqual vs == message same? Yes, message same, only condition differs.
			}
		} else {
			cond = got + " != " + want
			msg = equalMsgNoSub(fi, iFlag, namedFlag, got, want)
		}
		sb.WriteString(indent + "if " + got + " := " + call + "; " + cond + " {\n")
		sb.WriteString(indent + "\t" + msg + "\n")
		sb.WriteString(indent + "}\n")
		return sb.String()
	}
	if len(fi.Results) == 1 && fi.HasError {
		r := fi.Results[0]
		got := r.GotName
		want := "tt." + r.WantName
		sb.WriteString(indent + got + ", err := " + call + "\n")
		sb.WriteString(indent + "if (err != nil) != tt.wantErr {\n")
		sb.WriteString(indent + "\t" + errorMsgNoSub(fi, iFlag, namedFlag) + "\n")
		sb.WriteString(indent + "\tcontinue\n")
		sb.WriteString(indent + "}\n")
		sb.WriteString(indent + "if tt.wantErr {\n")
		sb.WriteString(indent + "\treturn\n")
		sb.WriteString(indent + "}\n")
		var cond, msg string
		if r.NeedsDeepEqual {
			if useGoCmpFlag {
				cond = "!cmp.Equal(" + want + ", " + got + ")"
				msg = cmpMsgNoSub(fi, iFlag, namedFlag, got, want)
			} else {
				cond = "!reflect.DeepEqual(" + got + ", " + want + ")"
				msg = equalMsgNoSub(fi, iFlag, namedFlag, got, want)
			}
		} else {
			cond = got + " != " + want
			msg = equalMsgNoSub(fi, iFlag, namedFlag, got, want)
		}
		sb.WriteString(indent + "if " + cond + " {\n")
		sb.WriteString(indent + "\t" + msg + "\n")
		sb.WriteString(indent + "}\n")
		return sb.String()
	}
	if len(fi.Results) > 1 && !fi.HasError {
		var gots []string
		for _, r := range fi.Results {
			gots = append(gots, r.GotName)
		}
		sb.WriteString(indent + strings.Join(gots, ", ") + " := " + call + "\n")
		for _, r := range fi.Results {
			got := r.GotName
			want := "tt." + r.WantName
			var cond, msg string
			if r.NeedsDeepEqual {
				if useGoCmpFlag {
					cond = "!cmp.Equal(" + want + ", " + got + ")"
					msg = cmpMsgMultiNoSub(fi, iFlag, namedFlag, got, want, r)
				} else {
					cond = "!reflect.DeepEqual(" + got + ", " + want + ")"
					msg = equalMsgMultiNoSub(fi, iFlag, namedFlag, got, want, r)
				}
			} else {
				cond = got + " != " + want
				msg = equalMsgMultiNoSub(fi, iFlag, namedFlag, got, want, r)
			}
			sb.WriteString(indent + "if " + cond + " {\n")
			sb.WriteString(indent + "\t" + msg + "\n")
			sb.WriteString(indent + "}\n")
		}
		return sb.String()
	}
	if len(fi.Results) > 1 && fi.HasError {
		var gots []string
		for _, r := range fi.Results {
			gots = append(gots, r.GotName)
		}
		gots = append(gots, "err")
		sb.WriteString(indent + strings.Join(gots, ", ") + " := " + call + "\n")
		sb.WriteString(indent + "if (err != nil) != tt.wantErr {\n")
		sb.WriteString(indent + "\t" + errorMsgNoSub(fi, iFlag, namedFlag) + "\n")
		sb.WriteString(indent + "\tcontinue\n")
		sb.WriteString(indent + "}\n")
		sb.WriteString(indent + "if tt.wantErr {\n")
		sb.WriteString(indent + "\treturn\n")
		sb.WriteString(indent + "}\n")
		for _, r := range fi.Results {
			got := r.GotName
			want := "tt." + r.WantName
			var cond, msg string
			if r.NeedsDeepEqual {
				if useGoCmpFlag {
					cond = "!cmp.Equal(" + want + ", " + got + ")"
					msg = cmpMsgMultiNoSub(fi, iFlag, namedFlag, got, want, r)
				} else {
					cond = "!reflect.DeepEqual(" + got + ", " + want + ")"
					msg = equalMsgMultiNoSub(fi, iFlag, namedFlag, got, want, r)
				}
			} else {
				cond = got + " != " + want
				msg = equalMsgMultiNoSub(fi, iFlag, namedFlag, got, want, r)
			}
			sb.WriteString(indent + "if " + cond + " {\n")
			sb.WriteString(indent + "\t" + msg + "\n")
			sb.WriteString(indent + "}\n")
		}
		return sb.String()
	}
	return sb.String()
}

func buildCallNoSub(fi FuncInfo, recvVar string, namedFlag bool) string {
	// For nosubtests, call is same as subtests (with tt.args)? Actually for nosubtests, args still tt.args (since loop has tt, except for "for range" bug where tt undefined but call has no args? For void with no args, call is Foo() without tt, so fine even with "for range".
	// For error-only with no args but with wantErr (bug, loop "for range" but call Foo() without tt, and check uses tt.wantErr with undefined tt? That's bug, but call itself is fine (no tt). Good.
	// For args case with nosubtests, loop has tt, call uses tt.args. Good.
	// So same as buildCall.
	if recvVar == "" && fi.IsMethod && !fi.HasFields && !fi.IsStructRecv && !fi.IsGenericRecv {
		// Non-struct direct: tt.DirectName
		recvVar = "tt." + fi.DirectName
		// buildCall expects recvVar for HasFields vs direct? For non-struct, buildCall uses "tt."+DirectName directly, not recvVar? Actually buildCall for non-struct uses "tt."+DirectName, ignoring recvVar. So for nosubtests, same.
		// To avoid duplication, just call buildCall with appropriate recvVar.
		// For non-struct, buildCall will ignore recvVar and use tt.DirectName. Good.
		// For struct empty, buildCall uses recvVar (which is DirectName without tt). Good.
		// So we can just call buildCall.
		return buildCall(fi, recvVar)
	}
	return buildCall(fi, recvVar)
}
